% and carry the examples of the ISO/IEC 13211-1 standard and of the
% conformance testing framework of Peter Szabo and Peter Szeredi.
% Generated by lang/stralog/tests/mkiso.py: v(Name, Expected, Goal).

two(2).
call_n_maplist(_Cont, []).
call_n_maplist(Cont, [E|Es]) :-
	call(Cont, E),
	call_n_maplist(Cont, Es).

v(iso_call_N_01, true, (call(integer, 3))).
v(iso_call_N_02, true(F == c), (call(functor(F,c), 0))).
v(iso_call_N_03, true(Atom == prolog), (call(call(call(atom_concat, pro), log), Atom))).
v(iso_call_N_05, false, (call(;, (true->fail), _X=1))).
v(iso_call_N_06, true, (call_n_maplist(>(3), [1, 2]))).
v(iso_call_N_07, false, (call_n_maplist(>(3), [1, 2, 3]))).
v(iso_call_N_08, true(Xs == []), (call_n_maplist(=(_X), Xs))).
